uint8_t *dxm_splash_rgba(void){
    uint8_t *out = malloc((size_t)DXM_SPLASH_W * DXM_SPLASH_HT * 4);
    if (!out) return 0;
    size_t o = 0;
    for (size_t i = 0; i + 6 <= sizeof dxm_splash_rle; i += 6) {
        unsigned n = dxm_splash_rle[i] | (dxm_splash_rle[i+1] << 8);
        while (n--) {
            out[o++] = dxm_splash_rle[i+2]; out[o++] = dxm_splash_rle[i+3];
            out[o++] = dxm_splash_rle[i+4]; out[o++] = dxm_splash_rle[i+5];
        }
    }
    return out;
}
